import React from 'react';
import { motion } from 'framer-motion';
import { Code2, Database, BarChart3, Settings2 } from 'lucide-react';

const Skills = () => {
  // Categorize provided skills strictly from user's data
  const skillCategories = [
    {
      title: "Core Languages & Foundations",
      icon: <Code2 className="w-5 h-5 text-cyan-400" />,
      skills: ["Python", "SQL", "C++", "Pandas", "NumPy", "DAX"]
    },
    {
      title: "Databases & Management",
      icon: <Database className="w-5 h-5 text-teal-400" />,
      skills: ["MySQL", "MongoDB"]
    },
    {
      title: "BI & Analysis Tools",
      icon: <BarChart3 className="w-5 h-5 text-emerald-400" />,
      skills: ["Power BI", "Tableau", "Excel", "Google Cloud Platform (GCP)"]
    },
    {
      title: "Workflow & Methodologies",
      icon: <Settings2 className="w-5 h-5 text-teal-500" />,
      skills: ["SDLC", "Agile Methodology", "Git", "GitHub", "Problem Solving", "Team Collaboration", "Global Communication"]
    }
  ];

  return (
    <section id="skills" className="py-20 bg-dark-900/40 relative border-t border-slate-900">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="mb-12">
          <span className="text-xs font-mono text-cyber-400 tracking-widest uppercase">Technological Spectrum</span>
          <h2 className="text-3xl font-bold text-white mt-1">Skills & Tools</h2>
          <div className="h-0.5 w-12 bg-cyber-500 mt-2" />
        </div>

        {/* Bento-like Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {skillCategories.map((category, idx) => (
            <motion.div 
              key={idx}
              initial={{ opacity: 0, y: 15 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4, delay: idx * 0.1 }}
              className="bg-dark-950 border border-slate-800/80 hover:border-slate-700/80 p-6 rounded-xl transition-all duration-300 relative overflow-hidden group"
            >
              {/* Hover highlight overlay */}
              <div className="absolute inset-0 bg-gradient-to-tr from-cyber-500/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" />

              <div className="flex items-center gap-3 mb-5 pb-3 border-b border-slate-800/60">
                <div className="p-2 rounded-lg bg-slate-900 border border-slate-800">
                  {category.icon}
                </div>
                <h3 className="font-bold text-white font-sans text-base sm:text-lg">
                  {category.title}
                </h3>
              </div>

              <div className="flex flex-wrap gap-2.5">
                {category.skills.map((skill) => (
                  <span 
                    key={skill}
                    className="px-3 py-1.5 rounded-lg bg-slate-900/60 text-slate-300 hover:text-cyber-300 hover:bg-slate-900 border border-slate-800/80 hover:border-cyber-500/30 text-xs font-mono transition-all duration-200 cursor-default"
                  >
                    {skill}
                  </span>
                ))}
              </div>
            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Skills;

import React from 'react';
import { motion } from 'framer-motion';
import { Briefcase, Calendar, Building2, CheckCircle2 } from 'lucide-react';

const Experience = () => {
  const experiences = [
    {
      companyname: "SortMyPrep",
      role: "AI Model Finetuning Intern",
      period: "April 2026 - July 2026",
      points: [
        "Curated, validated, and structured 80+ academic datasets for AI-powered learning systems by performing OCR validation, data cleaning, and document quality assurance.",
        "Processed complex mathematical and technical documents by correcting OCR-generated inconsistencies and normalizing structured content to improve downstream AI model performance.",
        "Collaborated with internal AI operations to improve data reliability, annotation quality, and preprocessing pipelines supporting model fine-tuning and educational AI products."
      ]
    },
    {
      companyname: "Infosys Springboard",
      role: "Data Visualization Intern",
      period: "Nov 2024 - Jan 2025",
      points: [
        "Conducted exploratory data analysis (EDA) on urban GDP and socio-economic datasets to identify regional growth trends.",
        "Developed dynamic Power BI dashboards featuring custom DAX measures and interactive filtering for comparative visual analysis.",
        "Presented key data-driven insights and interactive reports to a panel of stakeholders and upper management."
      ]
    }
  ];

  return (
    <section id="experience" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="mb-12 text-center sm:text-left">
          <span className="text-xs font-mono text-cyber-400 tracking-widest uppercase">Professional History</span>
          <h2 className="text-3xl font-bold text-white mt-1">Work Experience</h2>
          <div className="h-0.5 w-12 bg-cyber-500 mt-2 mx-auto sm:mx-0" />
        </div>

        {/* Timeline List */}
        <div className="relative border-l border-slate-800 max-w-5xl mx-auto sm:ml-4">
          {experiences.map((exp, idx) => (
            <motion.div 
              key={idx}
              initial={{ opacity: 0, x: -15 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true, margin: "-100px" }}
              transition={{ duration: 0.5, delay: idx * 0.1 }}
              className="relative pl-6 sm:pl-10 pb-12 last:pb-2 group"
            >
              {/* Point Indicator */}
              <div className="absolute left-[-6px] top-1.5 w-3 h-3 rounded-full bg-dark-950 border-2 border-cyber-400 group-hover:bg-cyber-400 transition-colors duration-300" />

              {/* Glow Accent behind timeline marker */}
              <div className="absolute left-[-14px] top-[-6px] w-7 h-7 rounded-full bg-cyber-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none" />

              {/* Main Content Area */}
              <div className="bg-dark-900 border border-slate-800/80 rounded-xl p-6 hover:border-slate-700/80 transition-all duration-300 shadow-md">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-white group-hover:text-cyber-300 transition-colors">
                      {exp.role}
                    </h3>
                    <div className="flex flex-wrap gap-2 items-center text-sm text-slate-400 mt-1">
                      <span className="flex items-center gap-1 font-semibold text-slate-300">
                        <Building2 className="w-4 h-4 text-cyber-500" />
                        {exp.companyname}
                      </span>
                    </div>
                  </div>
                  <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-md bg-slate-950 border border-slate-800 text-xs font-mono text-slate-400">
                    <Calendar className="w-3.5 h-3.5 text-cyber-400" />
                    {exp.period}
                  </span>
                </div>

                {/* Bullets List */}
                <ul className="space-y-3 pt-2 border-t border-slate-800/60">
                  {exp.points.map((point, pIdx) => (
                    <li key={pIdx} className="flex items-start gap-2.5 text-sm text-slate-400 leading-relaxed">
                      <CheckCircle2 className="w-4 h-4 text-cyber-400 mt-1 shrink-0" />
                      <span>{point}</span>
                    </li>
                  ))}
                </ul>
              </div>

            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Experience;

import React from 'react';
import { ChevronUp } from 'lucide-react';

const Footer = () => {
  return (
    <footer className="border-t border-slate-900 bg-dark-950 py-10 relative z-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col sm:flex-row justify-between items-center gap-6">

          {/* Logo Brand info */}
          <div className="text-center sm:text-left">
            <span className="font-sans font-bold text-slate-200 tracking-tight text-sm">
              Aayush Nisar
            </span>
            <span className="block text-[10px] text-slate-500 font-mono tracking-wider mt-0.5">
              AI & Data Science Student Professional © {new Date().getFullYear()}
            </span>
          </div>

          {/* Quick anchor scroll-up node */}
          <div>
            <a 
              href="#"
              className="p-2.5 rounded-lg bg-dark-900 border border-slate-800 hover:border-cyber-500/20 text-slate-400 hover:text-cyber-400 transition-all flex items-center gap-1.5 text-xs font-mono"
              aria-label="Back to top"
            >
              <span>System Top</span>
              <ChevronUp className="w-4 h-4" />
            </a>
          </div>

        </div>
      </div>
    </footer>
  );
};

export default Footer;

import React from 'react';
import { motion } from 'framer-motion';
import { Award, Calendar, CheckSquare } from 'lucide-react';

const Certifications = () => {
  const certs = [
    {
      name: "OCI 2025 Certified Data Science Professional",
      date: "Oct 2025"
    },
    {
      name: "Data Analysis Certification",
      date: "Aug 2024"
    },
    {
      name: "Google AI Essentials",
      date: "July 2024"
    }
  ];

  return (
    <section id="certifications" className="py-20 bg-dark-900/30 border-t border-slate-900 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="mb-12">
          <span className="text-xs font-mono text-cyber-400 tracking-widest uppercase">Verified Standards</span>
          <h2 className="text-3xl font-bold text-white mt-1">Certifications</h2>
          <div className="h-0.5 w-12 bg-cyber-500 mt-2" />
        </div>

        {/* Certifications Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {certs.map((cert, idx) => (
            <motion.div 
              key={idx}
              initial={{ opacity: 0, scale: 0.98 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4, delay: idx * 0.1 }}
              className="bg-dark-950 border border-slate-800/80 p-5 rounded-xl flex items-start gap-4 hover:border-slate-700 transition-colors group"
            >
              <div className="p-2.5 rounded-lg bg-cyber-500/5 border border-cyber-500/20 text-cyber-400 shrink-0">
                <Award className="w-5 h-5 group-hover:scale-110 transition-transform" />
              </div>

              <div className="space-y-1.5">
                <h3 className="font-bold text-white text-sm sm:text-base leading-snug">
                  {cert.name}
                </h3>
                <div className="flex items-center gap-1.5 text-xs text-slate-400 font-mono">
                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                  <span>{cert.date}</span>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Certifications;

