import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X, Github, Linkedin, Mail, Cpu } from 'lucide-react';

const Header = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'About', href: '#about' },
    { name: 'Experience', href: '#experience' },
    { name: 'Skills', href: '#skills' },
    { name: 'Projects', href: '#projects' },
    { name: 'Certifications', href: '#certifications' },
    { name: 'Contact', href: '#contact' },
  ];

  return (
    <header className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${
      scrolled 
        ? 'bg-dark-950/80 backdrop-blur-md border-b border-cyber-500/10 py-4 shadow-lg shadow-dark-950/50' 
        : 'bg-transparent py-6'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between">

          {/* Logo / Personal Brand */}
          <a href="#" className="flex items-center gap-2.5 group">
            <div className="relative flex items-center justify-center w-10 h-10 rounded-lg bg-cyber-500/10 border border-cyber-500/20 group-hover:border-cyber-400 group-hover:bg-cyber-500/20 transition-all duration-300">
              <Cpu className="w-5 h-5 text-cyber-400 group-hover:scale-110 transition-transform duration-300" />
              <div className="absolute inset-0 rounded-lg bg-cyber-400/20 blur opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
            </div>
            <div>
              <span className="font-sans font-bold text-lg text-slate-100 tracking-tight group-hover:text-cyber-300 transition-colors">
                Aayush Nisar
              </span>
              <span className="block text-[10px] text-cyber-400 font-mono tracking-wider">AI & DATA SCIENCE</span>
            </div>
          </a>

          {/* Desktop Navigation Links */}
          <nav className="hidden md:flex items-center gap-8">
            <ul className="flex items-center gap-6">
              {navLinks.map((link) => (
                <li key={link.name}>
                  <a 
                    href={link.href} 
                    className="relative text-sm font-medium text-slate-400 hover:text-cyber-300 transition-colors duration-200 group"
                  >
                    {link.name}
                    <span className="absolute bottom-[-6px] left-0 w-0 h-[2px] bg-cyber-400 transition-all duration-300 group-hover:w-full" />
                  </a>
                </li>
              ))}
            </ul>

            {/* Quick Actions / External Links */}
            <div className="flex items-center gap-4 pl-6 border-l border-slate-800">
              <a 
                href="https://github.com/7Aayush11" 
                target="_blank" 
                rel="noreferrer" 
                className="text-slate-400 hover:text-cyber-400 transition-colors"
                aria-label="GitHub"
              >
                <Github className="w-5 h-5" />
              </a>
              <a 
                href="https://linkedin.com/in/aayush-nisar" 
                target="_blank" 
                rel="noreferrer" 
                className="text-slate-400 hover:text-cyber-400 transition-colors"
                aria-label="LinkedIn"
              >
                <Linkedin className="w-5 h-5" />
              </a>
            </div>
          </nav>

          {/* Mobile Menu Toggle */}
          <div className="flex md:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="p-2 rounded-lg bg-slate-900 border border-slate-800 text-slate-300 hover:text-cyber-400 hover:border-cyber-500/40 transition-colors"
              aria-label="Toggle navigation menu"
            >
              {isOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Drawer */}
      <AnimatePresence>
        {isOpen && (
          <motion.div 
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden bg-dark-900 border-b border-slate-800/80 overflow-hidden"
          >
            <div className="px-4 pt-4 pb-6 space-y-3">
              {navLinks.map((link) => (
                <a
                  key={link.name}
                  href={link.href}
                  onClick={() => setIsOpen(false)}
                  className="block px-3 py-2 rounded-lg text-base font-medium text-slate-300 hover:bg-slate-800/50 hover:text-cyber-400 transition-all"
                >
                  {link.name}
                </a>
              ))}
              <div className="pt-4 border-t border-slate-800 flex items-center gap-6 px-3">
                <a 
                  href="https://github.com/7Aayush11" 
                  target="_blank" 
                  rel="noreferrer" 
                  className="text-slate-400 hover:text-cyber-400 flex items-center gap-2"
                >
                  <Github className="w-5 h-5" /> GitHub
                </a>
                <a 
                  href="https://linkedin.com/in/aayush-nisar" 
                  target="_blank" 
                  rel="noreferrer" 
                  className="text-slate-400 hover:text-cyber-400 flex items-center gap-2"
                >
                  <Linkedin className="w-5 h-5" /> LinkedIn
                </a>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};

export default Header;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AboutEducation from './components/AboutEducation';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Projects from './components/Projects';
import Certifications from './components/Certifications';
import Contact from './components/Contact';
import Footer from './components/Footer';

function App() {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="relative min-h-screen font-sans selection:bg-cyber-500/20 text-slate-300">
      {/* Background Interactive Radial Glow */}
      <div 
        className="fixed inset-0 pointer-events-none z-30 transition-opacity duration-300 opacity-50 hidden md:block"
        style={{
          background: `radial-gradient(600px circle at ${mousePos.x}px ${mousePos.y}px, rgba(20, 184, 166, 0.06), transparent 85%)`
        }}
      />

      {/* Global Background Grid Pattern */}
      <div className="fixed inset-0 data-grid pointer-events-none z-10 opacity-70" />

      {/* Decorative Blur Orbs */}
      <div className="fixed top-[-10%] right-[-10%] w-[500px] h-[500px] rounded-full bg-cyber-500/5 blur-[120px] pointer-events-none z-0" />
      <div className="fixed bottom-[-10%] left-[-10%] w-[600px] h-[600px] rounded-full bg-teal-600/5 blur-[130px] pointer-events-none z-0" />

      {/* Layout Grid Wrapper */}
      <div className="relative z-20 flex flex-col min-h-screen">
        <Header />

        <main className="flex-grow">
          <Hero />
          <AboutEducation />
          <Experience />
          <Skills />
          <Projects />
          <Certifications />
          <Contact />
        </main>

        <Footer />
      </div>
    </div>
  );
}

export default App;

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    background-color: #030712;
  }
}

/* Custom Webkit scrollbar for sleek dark look */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: #030712;
}
::-webkit-scrollbar-thumb {
  background: #1f2937;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #14b8a6;
}

/* Accent lighting effects */
.radial-glow {
  background: radial-gradient(circle 600px at var(--x, 0px) var(--y, 0px), rgba(20, 184, 166, 0.15), transparent 80%);
}

.data-grid {
  background-image: radial-gradient(rgba(20, 184, 166, 0.08) 1px, transparent 1px);
  background-size: 24px 24px;
}

import React from 'react';
import { motion } from 'framer-motion';
import { ArrowUpRight, BarChart, Database, Cpu, Layers } from 'lucide-react';

const Projects = () => {
  const projects = [
    {
      name: "Customer Segmentation using RFM Analysis",
      description: "Analyzed e-commerce transactions using Recency-Frequency-Monetary (RFM) metrics to evaluate customer value. Applied KMeans clustering to segment customers into four distinct engagement groups.",
      techstack: ["Python", "KMeans", "Tableau"],
      category: "Data Science & Clustering",
      imgSlot: "proj-rfm-01"
    },
    {
      name: "HR Analytics & Attrition Prediction",
      description: "Utilized Python to clean and analyze HR datasets, identifying critical drivers behind employee attrition. Built a logistic regression model to classify attrition risk, achieving 89% accuracy and supporting data-driven human capital management.",
      techstack: ["Python (Pandas, Scikit-learn)", "Power BI"],
      category: "Predictive Modeling",
      imgSlot: "proj-hr-02"
    },
    {
      name: "Adventure Works Sales Dashboard",
      description: "Designed a comprehensive BI dashboard using Power BI to analyze sales trends and customer segmentation. Implemented advanced DAX functions to calculate business-critical KPIs and enhance storytelling through interactive visuals.",
      techstack: ["Power BI", "Excel"],
      category: "Business Intelligence",
      imgSlot: "proj-sales-03"
    }
  ];

  return (
    <section id="projects" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="mb-12">
          <span className="text-xs font-mono text-cyber-400 tracking-widest uppercase">Portfolio Works</span>
          <h2 className="text-3xl font-bold text-white mt-1">Featured Projects</h2>
          <div className="h-0.5 w-12 bg-cyber-500 mt-2" />
        </div>

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {projects.map((proj, idx) => (
            <motion.div 
              key={idx}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: idx * 0.1 }}
              className="bg-dark-900 border border-slate-800/80 hover:border-cyber-500/20 rounded-xl flex flex-col justify-between transition-all duration-300 hover:translate-y-[-4px] group relative overflow-hidden"
            >
              {/* Project Preview Image Placeholder */}
              <div className="h-48 w-full bg-slate-950 overflow-hidden border-b border-slate-800">
                <img 
                  src={`https://placehold.co/600x400/0f172a/94a3b8?text=Project+Preview`} 
                  alt={proj.name}
                  data-img-slot={proj.imgSlot}
                  data-img-label={`Project image for ${proj.name}`}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                />
              </div>

              <div className="p-6 flex flex-col flex-grow">
                <div className="space-y-4">
                  {/* Visual Category Node */}
                  <div className="flex justify-between items-start">
                    <span className="text-[10px] font-mono text-cyber-400 uppercase tracking-widest px-2.5 py-1 rounded bg-cyber-500/5 border border-cyber-500/15">
                      {proj.category}
                    </span>

                    {/* Miniature aesthetic icon */}
                    <div className="text-slate-600 group-hover:text-cyber-400 transition-colors">
                      {idx === 0 && <Layers className="w-5 h-5" />}
                      {idx === 1 && <Cpu className="w-5 h-5" />}
                      {idx === 2 && <BarChart className="w-5 h-5" />}
                    </div>
                  </div>

                  <h3 className="text-lg font-bold text-white group-hover:text-cyber-300 transition-colors line-clamp-2">
                    {proj.name}
                  </h3>

                  <p className="text-slate-400 text-sm leading-relaxed line-clamp-3">
                    {proj.description}
                  </p>
                </div>

                {/* Tech Stack and footer */}
                <div className="mt-6 pt-4 border-t border-slate-800/60">
                  <div className="flex flex-wrap gap-1.5">
                    {proj.techstack.map((tech) => (
                      <span 
                        key={tech} 
                        className="px-2 py-1 rounded bg-slate-950 border border-slate-800 text-[10px] font-mono text-slate-400"
                      >
                        {tech}
                      </span>
                    ))}
                  </div>
                </div>
              </div>

            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Projects;
